import{_ as t,o as s,c as e,a5 as n}from"./chunks/framework.Bt0SrEfo.js";const u=JSON.parse('{"title":"二、客户面谈","description":"","frontmatter":{},"headers":[],"relativePath":"副业/保险展业/02-客户面谈.md","filePath":"副业/保险展业/02-客户面谈.md","lastUpdated":1792500960000}'),i={name:"副业/保险展业/02-客户面谈.md"};function l(o,a,p,d,h,r){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="二、客户面谈" tabindex="-1">二、客户面谈 <a class="header-anchor" href="#二、客户面谈" aria-label="Permalink to &quot;二、客户面谈&quot;">​</a></h1><p>一对一深度沟通，了解客户真实需求，是整个展业过程的核心环节。</p><h2 id="_1-面谈前准备" tabindex="-1">1. 面谈前准备 <a class="header-anchor" href="#_1-面谈前准备" aria-label="Permalink to &quot;1. 面谈前准备&quot;">​</a></h2><h3 id="资料准备" tabindex="-1">资料准备 <a class="header-anchor" href="#资料准备" aria-label="Permalink to &quot;资料准备&quot;">​</a></h3><ul><li>客户背景信息（来源、年龄、职业、家庭情况）</li><li>公司产品手册（不同险种的适用场景）</li><li>保障缺口分析表（空白）</li><li>纸、笔</li></ul><h3 id="目标设定" tabindex="-1">目标设定 <a class="header-anchor" href="#目标设定" aria-label="Permalink to &quot;目标设定&quot;">​</a></h3><ul><li><strong>不是卖产品，是帮客户解决问题</strong></li><li>了解客户的担忧、目标和现有保障</li><li>找到 1-2 个核心需求作为切入点</li></ul><h2 id="_2-面谈流程" tabindex="-1">2. 面谈流程 <a class="header-anchor" href="#_2-面谈流程" aria-label="Permalink to &quot;2. 面谈流程&quot;">​</a></h2><h3 id="_1-破冰-5分钟" tabindex="-1">① 破冰（5分钟） <a class="header-anchor" href="#_1-破冰-5分钟" aria-label="Permalink to &quot;① 破冰（5分钟）&quot;">​</a></h3><p>寒暄为主，拉近距离：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;上次活动聊得挺开心的，今天就是想好好了解一下您的情况，</span></span>
<span class="line"><span>看看有没有能帮到您的地方。&quot;</span></span></code></pre></div><h3 id="_2-了解现状-15分钟" tabindex="-1">② 了解现状（15分钟） <a class="header-anchor" href="#_2-了解现状-15分钟" aria-label="Permalink to &quot;② 了解现状（15分钟）&quot;">​</a></h3><p>用开放式问题收集信息：</p><p><strong>家庭结构</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;家里几口人？孩子多大？&quot;</span></span>
<span class="line"><span>&quot;父母身体还好吗？有没有帮您带孩子？&quot;</span></span></code></pre></div><p><strong>经济状况</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;您家每月的固定支出大概在什么水平？&quot;</span></span>
<span class="line"><span>&quot;有没有房贷、车贷这类负债？&quot;</span></span></code></pre></div><p><strong>现有保障</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;您家里已经买了哪些保险？&quot;</span></span>
<span class="line"><span>&quot;单位的团险保障够吗？&quot;</span></span></code></pre></div><p><strong>担忧与目标</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;您现在最担心的事情是什么？医疗、教育还是养老？&quot;</span></span>
<span class="line"><span>&quot;您希望给家庭提供什么样的保障水平？&quot;</span></span></code></pre></div><h3 id="_3-需求分析-10分钟" tabindex="-1">③ 需求分析（10分钟） <a class="header-anchor" href="#_3-需求分析-10分钟" aria-label="Permalink to &quot;③ 需求分析（10分钟）&quot;">​</a></h3><p>根据收集到的信息，帮客户梳理保障缺口：</p><table tabindex="0"><thead><tr><th>风险类型</th><th>客户提到</th><th>缺口分析</th></tr></thead><tbody><tr><td>重疾风险</td><td>提到看病贵/没有商业医疗险</td><td>医疗险+重疾险</td></tr><tr><td>意外风险</td><td>经常开车/出差</td><td>意外险</td></tr><tr><td>家庭责任</td><td>房贷+孩子教育</td><td>定期寿险</td></tr><tr><td>养老规划</td><td>提到养老/退休金</td><td>养老险/储蓄险</td></tr><tr><td>教育金</td><td>孩子还小/教育规划</td><td>教育金险</td></tr></tbody></table><h3 id="_4-方案预告-5分钟" tabindex="-1">④ 方案预告（5分钟） <a class="header-anchor" href="#_4-方案预告-5分钟" aria-label="Permalink to &quot;④ 方案预告（5分钟）&quot;">​</a></h3><p>不要直接给方案，先确认方向：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;根据您说的情况，我理解您最关心的可能是医疗和养老这两块，</span></span>
<span class="line"><span>我这边帮您做个方案，您看方便吗？&quot;</span></span></code></pre></div><p>→ 确认客户同意后再出方案。</p><h2 id="_3-常见话术" tabindex="-1">3. 常见话术 <a class="header-anchor" href="#_3-常见话术" aria-label="Permalink to &quot;3. 常见话术&quot;">​</a></h2><h3 id="客户说-我已经有社保了" tabindex="-1">客户说&quot;我已经有社保了&quot; <a class="header-anchor" href="#客户说-我已经有社保了" aria-label="Permalink to &quot;客户说&quot;我已经有社保了&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;社保是我们每个人最基础的保障，很重要。</span></span>
<span class="line"><span>但社保是有报销比例和范围限制的，比如很多进口药、自费项目</span></span>
<span class="line"><span>社保就不能报，所以需要商业险来做补充。&quot;</span></span></code></pre></div><h3 id="客户说-保险都是骗人的" tabindex="-1">客户说&quot;保险都是骗人的&quot; <a class="header-anchor" href="#客户说-保险都是骗人的" aria-label="Permalink to &quot;客户说&quot;保险都是骗人的&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我理解您的担心，确实以前有些不太好的体验。</span></span>
<span class="line"><span>现在保险行业监管越来越严格了，我们公司是 XXXXX，</span></span>
<span class="line"><span>您可以先了解一下，不一定要买，就当多一个信息渠道。&quot;</span></span></code></pre></div><h3 id="客户说-我没钱" tabindex="-1">客户说&quot;我没钱&quot; <a class="header-anchor" href="#客户说-我没钱" aria-label="Permalink to &quot;客户说&quot;我没钱&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我完全理解。其实保险不一定要花很多钱，我们可以先从</span></span>
<span class="line"><span>最紧急的保障开始，比如每年 XXXX 元，先把医疗险配上，</span></span>
<span class="line"><span>等经济宽裕了再逐步完善。您看这样可以吗？&quot;</span></span></code></pre></div><h3 id="客户说-我和家人商量一下" tabindex="-1">客户说&quot;我和家人商量一下&quot; <a class="header-anchor" href="#客户说-我和家人商量一下" aria-label="Permalink to &quot;客户说&quot;我和家人商量一下&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;应该的，买保险是家庭大事，确实需要商量。</span></span>
<span class="line"><span>我可以先把方案发给您，您和家人一起看看，</span></span>
<span class="line"><span>有什么疑问随时联系我。&quot;</span></span></code></pre></div><h2 id="_4-面谈后跟进" tabindex="-1">4. 面谈后跟进 <a class="header-anchor" href="#_4-面谈后跟进" aria-label="Permalink to &quot;4. 面谈后跟进&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>动作</th></tr></thead><tbody><tr><td>当天</td><td>发微信确认客户安全到家</td></tr><tr><td>1-2天</td><td>发送纸质/电子方案</td></tr><tr><td>3-5天</td><td>主动询问方案是否看完，有无疑问</td></tr><tr><td>1-2周</td><td>约第二次面谈，推进决策</td></tr></tbody></table><h2 id="_5-注意事项" tabindex="-1">5. 注意事项 <a class="header-anchor" href="#_5-注意事项" aria-label="Permalink to &quot;5. 注意事项&quot;">​</a></h2><ul><li>❌ 不要一上来就推荐产品，先了解需求</li><li>❌ 不要夸大收益或隐瞒免责条款</li><li>❌ 不要逼迫客户做决定，给客户思考空间</li><li>✅ 真诚沟通，专业建议，客户感受到你是帮他解决问题</li><li>✅ 做好记录，每次面谈后记录客户关键信息</li></ul>`,41)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
